css:
.print-format { font-size: 11px; color: #000; }
.dz-head { display: flex; justify-content: space-between; gap: 16px; border-bottom: 2px solid #000; padding-bottom: 8px; margin-bottom: 10px; }
.dz-head .seller .name { font-size: 16px; font-weight: 700; }
.dz-head .doc-title { text-align: right; }
.dz-head .doc-title h2 { margin: 0; font-size: 20px; letter-spacing: .05em; }
.dz-ids { font-size: 10px; line-height: 1.5; }
.dz-parties { display: flex; gap: 16px; margin-bottom: 10px; }
.dz-box { flex: 1; border: 1px solid #000; padding: 6px 8px; }
.dz-box .title { font-size: 9px; text-transform: uppercase; letter-spacing: .05em; margin-bottom: 3px; }
table.dz-items { width: 100%; border-collapse: collapse; }
table.dz-items th, table.dz-items td { border: 1px solid #000; padding: 4px 6px; }
table.dz-items th { background: #eee; font-size: 10px; text-transform: uppercase; }
table.dz-items td.num, table.dz-items th.num { text-align: right; white-space: nowrap; }
.dz-totals { width: 45%; margin-left: auto; margin-top: 8px; border-collapse: collapse; }
.dz-totals td { padding: 3px 6px; border: 1px solid #000; }
.dz-totals td.num { text-align: right; white-space: nowrap; }
.dz-totals tr.grand td { font-weight: 700; font-size: 13px; }
.dz-words { margin-top: 8px; font-style: italic; }
.dz-foot { display: flex; justify-content: space-between; gap: 16px; margin-top: 14px; }
.dz-stamp { width: 45%; height: 80px; border: 1px dashed #000; padding: 6px; font-size: 9px; text-transform: uppercase; }
.dz-note { font-size: 10px; margin-top: 8px; }
.dz-watermark { position: fixed; top: 40%; left: 10%; font-size: 64px; font-weight: 700; color: rgba(200,0,0,.25); transform: rotate(-30deg); z-index: 0; }

html:
{%- set co = frappe.get_doc("Company", doc.company) -%}
{%- set buyer = frappe.db.get_value("Customer", doc.customer, ["dz_rc", "dz_nif", "dz_nis", "dz_ai"], as_dict=1) or {} -%}
{%- set note = frappe.db.get_single_value("DZ Core Settings", "invoice_note") -%}
{#- A credit note (avoir) holds negative amounts: printed positive under its own title -#}
{%- set k = -1 if doc.is_return else 1 -%}
{#- Invoice discount: net_total is already after it, so it shows between the two HT totals -#}
{%- set remise = (doc.total - doc.net_total) if doc.discount_amount else 0 -%}
{%- if doc.docstatus == 2 %}<div class="dz-watermark">{{ (_("AVOIR ANNULÉ") if doc.is_return else _("FACTURE ANNULÉE")) if doc.doctype == "Sales Invoice" else _("ANNULÉ") }}</div>{% elif doc.docstatus == 0 %}<div class="dz-watermark">{{ _("BROUILLON") }}</div>{% endif -%}
<div class="dz-head">
	<div class="seller">
		<div class="name">{{ co.company_name }}</div>
		<div>{{ co.dz_legal_form or "" }}{% if co.dz_activity %} · {{ co.dz_activity }}{% endif %}</div>
		<div>{{ doc.company_address_display or "" }}</div>
		{%- if co.phone_no %}<div>{{ _("Tél.") }} {{ co.phone_no }}</div>{% endif %}
		<div class="dz-ids">
			{% if co.dz_rc %}{{ _("RC / Carte AE") }} : {{ co.dz_rc }}<br>{% endif %}
			{% if co.dz_nif %}{{ _("NIF") }} : {{ co.dz_nif }}{% endif %}{% if co.dz_nis %} · {{ _("NIS") }} : {{ co.dz_nis }}{% endif %}{% if co.dz_ai %} · {{ _("AI") }} : {{ co.dz_ai }}{% endif %}
			{% if co.dz_capital %}<br>{{ _("Capital social") }} : {{ montant(co.dz_capital) }} DA{% endif %}
		</div>
	</div>
	<div class="doc-title">
		<h2>{{ _("FACTURE D'AVOIR") if doc.is_return else _("FACTURE") }}</h2>
		<div>{{ _("N°") }} <strong>{{ doc.name }}</strong></div>
		<div>{{ _("Date") }} : {{ frappe.utils.formatdate(doc.posting_date) }}</div>
		{%- if doc.is_return and doc.return_against %}<div>{{ _("Facture d'origine") }} : {{ doc.return_against }}</div>{% endif %}
	</div>
</div>
<div class="dz-parties">
	<div class="dz-box">
		<div class="title">{{ _("Client") }}</div>
		<strong>{{ doc.customer_name }}</strong><br>
		{{ (doc.address_display or doc.shipping_address or "") }}
		<div class="dz-ids">
			{% if buyer.dz_rc %}{{ _("RC") }} : {{ buyer.dz_rc }}<br>{% endif %}
			{% if buyer.dz_nif %}{{ _("NIF") }} : {{ buyer.dz_nif }}{% endif %}{% if buyer.dz_nis %} · {{ _("NIS") }} : {{ buyer.dz_nis }}{% endif %}{% if buyer.dz_ai %} · {{ _("AI") }} : {{ buyer.dz_ai }}{% endif %}
		</div>
	</div>
	<div class="dz-box">
		<div class="title">{{ _("Règlement") }}</div>
		{{ _("Mode de paiement") }} : {{ doc.dz_payment_mode or "—" }}{% if doc.dz_payment_reference %}<br>{{ _("Référence") }} : {{ doc.dz_payment_reference }}{% if doc.dz_payment_reference_date %} {{ _("du") }} {{ frappe.utils.formatdate(doc.dz_payment_reference_date) }}{% endif %}{% if doc.dz_payment_bank %} · {{ doc.dz_payment_bank }}{% endif %}{% endif %}<br>
		{{ _("Date de règlement") }} : {{ frappe.utils.formatdate(doc.due_date) if doc.due_date else "—" }}
		{% if doc.po_no %}<br>{{ _("Votre commande") }} : {{ doc.po_no }}{% endif %}
	</div>
</div>
<table class="dz-items">
	<thead><tr>
		<th>{{ _("N°") }}</th><th>{{ _("Désignation") }}</th><th class="num">{{ _("Qté") }}</th><th>{{ _("Unité") }}</th>
		<th class="num">{{ _("Prix unitaire HT (DA)") }}</th><th class="num">{{ _("Montant HT (DA)") }}</th>
	</tr></thead>
	<tbody>
	{%- for row in doc.items %}
		<tr>
			<td>{{ row.idx }}</td>
			<td>{{ row.item_name }}{% if row.batch_no %} <span class="dz-ids">({{ _("lot") }} {{ row.batch_no }})</span>{% endif %}</td>
			<td class="num">{{ frappe.utils.fmt_money(k * row.qty, precision=3).rstrip("0").rstrip(",").rstrip(".") }}</td>
			<td>{{ row.uom }}</td>
			<td class="num">{{ montant(row.rate) }}</td>
			<td class="num">{{ montant(k * row.amount) }}</td>
		</tr>
	{%- endfor %}
	</tbody>
</table>
<table class="dz-totals">
	<tr><td>{{ _("Total HT (DA)") }}</td><td class="num">{{ montant(k * (doc.total if remise else doc.net_total)) }}</td></tr>
	{%- if remise %}
	<tr><td>{{ _("Remise") }}</td><td class="num">- {{ montant(k * remise) }}</td></tr>
	<tr><td>{{ _("Total HT après remise (DA)") }}</td><td class="num">{{ montant(k * doc.net_total) }}</td></tr>
	{%- endif %}
	{%- for tax in doc.taxes if tax.tax_amount_after_discount_amount and "vendeur" not in (tax.description or "") %}
	<tr><td>{{ (tax.description or "").split(" @ ")[0] }}</td><td class="num">{{ montant(k * tax.tax_amount_after_discount_amount) }}</td></tr>
	{%- endfor %}
	{%- if doc.rounded_total and doc.rounding_adjustment %}<tr><td>{{ _("Arrondi") }}</td><td class="num">{{ montant(k * doc.rounding_adjustment) }}</td></tr>{% endif %}
	<tr class="grand"><td>{{ _("Total TTC (DA)") if doc.taxes else (_("Total de l'avoir (DA)") if doc.is_return else _("Total à payer (DA)")) }}</td><td class="num">{{ montant(k * (doc.rounded_total or doc.grand_total)) }}</td></tr>
</table>
<div class="dz-words">{{ _("Arrêté le présent avoir à la somme de") if doc.is_return else _("Arrêtée la présente facture à la somme de") }} : {{ montant_en_lettres(k * (doc.rounded_total or doc.grand_total)) }}.</div>
<div class="dz-foot">
	<div class="dz-note">{% if note %}{{ note }}{% endif %}</div>
	<div class="dz-stamp">{{ _("Cachet et signature") }}</div>
</div>
